command:
kubectl patch deployment keycloak -n arvis-core --type=json -p='[
  {"op":"remove","path":"/spec/template/spec/containers/0/env/9"},
  {"op":"remove","path":"/spec/template/spec/containers/0/env/8"}
]' && kubectl rollout status deployment/keycloak -n arvis-core --timeout=120s

kubectl patch deployment keycloak -n arvis-core --type=json -p='[
  {"op":"add","path":"/spec/template/spec/containers/0/env/6","value":{"name":"DOMAIN","valueFrom":{"configMapKeyRef":{"name":"global-env","key":"DOMAIN"}}}},
  {"op":"add","path":"/spec/template/spec/containers/0/env/8","value":{"name":"KC_HOSTNAME","value":"auth.$(DOMAIN)"}}
]' && kubectl rollout status deployment/keycloak -n arvis-core --timeout=120s

kubectl exec deployment/mysql-master -n arvis-data -- mysql -uroot -p'6IK-7DVFh)J/yRvdk-m' arvis_superadmin -e "
INSERT INTO super_admin_users (email, password, first_name, last_name, is_active, is_verified)
VALUES ('admin@arvis.com.tr', 'KC_MANAGED', 'Arvis', 'SuperAdmin', 1, 1);

SET @uid = LAST_INSERT_ID();
INSERT INTO super_admins (user_id, is_active) VALUES (@uid, 1);

SELECT u.id, u.email, s.id as super_id, s.is_active 
FROM super_admin_users u 
JOIN super_admins s ON s.user_id = u.id 
WHERE u.email = 'admin@arvis.com.tr';
" 2>/dev/null
